/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, a=0;
  wire match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));
  always #5 clk = ~clk;

  task shift_bit(input bit b);
    begin
      a = b;
      @(posedge clk);
      #1;
      "'$display("t=%0t a=%0b a_tem? match=%0b", $time, a, match);
    end
  endtask

  initial begin
    repeat (1) @(posedge clk);
    rst_n = 1;
    // shift in 0111_0001
    shift_bit(0);
    shift_bit(1);
    shift_bit(1);
    shift_bit(1);
    shift_bit(0);
    shift_bit(0);
    shift_bit(0);
    shift_bit(1);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

